function parseTimeoutMs(value) {
  if (typeof value === "number") {
    return Math.round(value * 1000);
  }
  const s = String(value).trim().toLowerCase();
  if (s.endsWith("ms")) {
    return parseInt(s.slice(0, -2), 10);
  }
  if (s.endsWith("s")) {
    return parseInt(s.slice(0, -1), 10) * 1000;
  }
  if (s.endsWith("m")) {
    return parseInt(s.slice(0, -1), 10) * 60000;
  }
  return parseInt(s, 10) * 1000;
}

function parseEndpoint(value) {
  const s = String(value);
  const colon = s.lastIndexOf(":");
  if (colon !== -1) {
    const portStr = s.slice(colon + 1).trim();
    if (/^\d+$/.test(portStr)) {
      return { host: s.slice(0, colon), port: parseInt(portStr, 10) };
    }
  }
  return { host: s, port: 443 };
}

function parseTags(value) {
  let raw;
  if (Array.isArray(value)) {
    raw = value;
  } else if (typeof value === "string" && value.trim() !== "") {
    raw = value.split(",");
  } else {
    raw = [];
  }
  const tags = [];
  const seen = new Set();
  for (const item of raw) {
    const tag = String(item).trim().toLowerCase();
    if (tag === "" || seen.has(tag)) {
      continue;
    }
    seen.add(tag);
    tags.push(tag);
  }
  tags.sort();
  return tags;
}

function parseEnabled(value) {
  if (typeof value === "string") {
    const s = value.trim().toLowerCase();
    return s === "yes" || s === "true" || s === "on" || s === "1";
  }
  return value === 1 || value === true;
}

const v1Configs = tool("configs", {});

const notes = [];
for (const cfg of v1Configs) {
  const note = cfg.owner_note === undefined || cfg.owner_note === null ? "" : String(cfg.owner_note);
  notes.push(note);
}
const priorities = tool("judge_priorities", { notes: notes });

const v2Configs = [];
let index = 0;
for (const cfg of v1Configs) {
  const endpoint = parseEndpoint(cfg.endpoint);

  let retries = 0;
  if (cfg.retries !== undefined && cfg.retries !== null && cfg.retries !== "") {
    const parsed = parseInt(cfg.retries, 10);
    if (!isNaN(parsed)) {
      retries = parsed;
    }
  }

  v2Configs.push({
    name: cfg.name,
    timeoutMs: parseTimeoutMs(cfg.timeout),
    host: endpoint.host,
    port: endpoint.port,
    retries: retries,
    tags: parseTags(cfg.tags),
    enabled: parseEnabled(cfg.enabled),
    priority: priorities[index]
  });
  index++;
}

