const configs = tool("configs", {});

const notes = [];
for (const c of configs) {
  notes.push(c.owner_note == null ? "" : c.owner_note);
}
const priorities = tool("judge_priorities", { notes: notes });

function parseTimeoutMs(t) {
  if (typeof t === "number") {
    return Math.round(t * 1000);
  }
  const s = String(t).trim();
  if (s.endsWith("ms")) {
    return parseInt(s, 10);
  }
  if (s.endsWith("m")) {
    return parseInt(s, 10) * 60000;
  }
  if (s.endsWith("s")) {
    return parseInt(s, 10) * 1000;
  }
  return Math.round(parseFloat(s) * 1000);
}

function parseEndpoint(ep) {
  const s = String(ep);
  const i = s.lastIndexOf(":");
  if (i !== -1) {
    const portStr = s.slice(i + 1);
    const port = parseInt(portStr, 10);
    if (portStr !== "" && !isNaN(port)) {
      return { host: s.slice(0, i), port: port };
    }
  }
  return { host: s, port: 443 };
}

function parseRetries(r) {
  if (r == null) {
    return 0;
  }
  const n = parseInt(r, 10);
  return isNaN(n) ? 0 : n;
}

function parseTags(t) {
  const raw = [];
  if (Array.isArray(t)) {
    for (const x of t) {
      raw.push(String(x));
    }
  } else if (typeof t === "string") {
    const parts = t.split(",");
    for (const p of parts) {
      raw.push(p);
    }
  }
  const seen = {};
  const tags = [];
  for (const r of raw) {
    const v = r.trim().toLowerCase();
    if (v === "" || seen[v]) {
      continue;
    }
    seen[v] = true;
    tags.push(v);
  }
  tags.sort();
  return tags;
}

function parseEnabled(e) {
  if (e === true || e === 1) {
    return true;
  }
  if (e === false || e === 0) {
    return false;
  }
  const s = String(e).trim().toLowerCase();
  return s === "yes" || s === "true" || s === "on";
}

const result = [];
let index = 0;
for (const c of configs) {
  const ep = parseEndpoint(c.endpoint);
  result.push({
    name: c.name,
    timeoutMs: parseTimeoutMs(c.timeout),
    host: ep.host,
    port: ep.port,
    retries: parseRetries(c.retries),
    tags: parseTags(c.tags),
    enabled: parseEnabled(c.enabled),
    priority: priorities[index]
  });
  index++;
}

